import {
  Button,
  Divider,
  Form,
  Input,
  InputNumber,
  Row,
  Select,
  Spin,
  Upload,
  UploadFile,
  message,
} from "antd";
import React, {
  Fragment,
  useCallback,
  useEffect,
  useMemo,
  useState,
} from "react";
import { FundViewOutlined } from "@ant-design/icons";
import styled from "styled-components";
import { colocConfig, eqtlList, getColocConfig } from "src/service/api/home";
import LocalSingleFileUploader from "./LocalSingleFileUploader";
import { gwasFile } from "src/service/api/home";
import { useLocation, useNavigate } from "react-router-dom";
import useUploadProgress from "./component/useUploadProgress";
import { THRESHOLD_MAP_DETIAL } from "./ResultPage";
import { useAuthorize } from "..";
import Title from "antd/es/typography/Title";
const formItemLayout = {
  labelCol: { span: 6 },
  wrapperCol: { span: 14 },
};
const { Option } = Select;

const validFiles: string[] = ["tsv", "xlsx"];
const tools = ["coloc", "smr", "predixcan", "twas", "fastenloc", "ecaviar"];
export default function InputPage(props: {
  summaryInfo?: any;
  isLoadingForSummary?: boolean;
}) {
  const { summaryInfo, isLoadingForSummary = false } = props;
  const userAuth = useAuthorize();
  const [form] = Form.useForm();
  const [fileForm] = Form.useForm();
  const [eqtls, setEqtls] = useState<any>();
  const { progress, reset, onUploadProgress } = useUploadProgress();
  const [isLoading, setIsloading] = useState<boolean>(false);
  const navigate = useNavigate();

  useEffect(() => {
    if (!userAuth.isLogin || !localStorage.getItem("token")) {
      navigate("/login");
      return;
    }
  }, [navigate, userAuth.isLogin]);

  const isValidFileFormat = useCallback((name: string) => {
    const reg = new RegExp(`\\.(${validFiles.join("|")})$`);
    return true;
  }, []);
  const [fileList, setFileList] = useState<UploadFile[]>([]);
  useEffect(() => {
    (async function () {
      try {
        const eqtls: any = (await eqtlList())?.data?.data;
        setEqtls(eqtls);
      } catch (error) {}
    })();
  }, []);
  const submitForm = useCallback(async () => {
    try {
      setIsloading(true);
      const values = await form.validateFields();
      const res = await gwasFile({
        file: fileList[0],
        onUploadProgress,
      });
      await fileForm.validateFields();
      const gwas_param = {
        trait: values.trait,
        type: values.type,
        pval_threshold: parseFloat(values.pvalue_threshold),
        sample_size: parseInt(values.sample_size),
        rs_id: values.snp,
        chrom: values.chrom,
        position: values.position,
        beta: values.beta,
        effect_allele: values.effect_allele,
        other_allele: values.other_allele,
        p_value: values.p_value,
        standard_error: values.standard_error,
      };
      const tool_params = {
        a0: parseFloat(values.a0),
        a1: parseFloat(values.a1),
        p1: parseFloat(values.p1),
        p2: parseFloat(values.p2),
        p12: parseFloat(values.p12),
      };

      await colocConfig({
        gwas_params: JSON.stringify(gwas_param),
        tool_params: JSON.stringify(tool_params),
        gwas_raw_id: res,
        tissues: values.eqtls,
      });
      message.success("Submit Success");
      setIsloading(false);
      navigate(`/home/tasks`, {
        state: { menuKey: "8" },
      });
    } catch (e) {
      setIsloading(false);
      message.error("Submit Failed");
    }
  }, [fileForm, fileList, form, navigate, onUploadProgress]);

  const fileUploadProps = useMemo(
    () => ({
      beforeUpload(file: UploadFile) {
        const isLtFiveHM = (file?.size || 0) / 1024 / 1024 < 500;
        if (!isLtFiveHM) {
          message.error("Maximun allow file size in 500MB!");
          return;
        }
        setFileList([file]);
        return;
      },
      onRemove() {
        setFileList([]);
      },
      // this overrides fileList state of Upload component
      fileList,
    }),
    [fileList]
  );
  const resetFormHandler = useCallback(async () => {
    form.resetFields();
    fileForm.resetFields();
    reset();
  }, [fileForm, form, reset]);

  const initialValues = useMemo(() => {
    if (summaryInfo?.eqtl) {
      return {
        ...summaryInfo,
        pvalue_threshold: summaryInfo.gwas_pval_threshold || 0,
        standard_error: summaryInfo.se,
        p1: summaryInfo.tool_param[0],
        p2: summaryInfo.tool_param[1],
        p12: summaryInfo.tool_param[2],
        a0: summaryInfo.tool_param[3],
        a1: summaryInfo.tool_param[4],
        eqtls: [...summaryInfo.eqtl],
        tools,
      };
    } else {
      return {
        tools,
        pvalue_threshold: 0.00000005,
      };
    }
  }, [summaryInfo]);
  const readOnly = summaryInfo?.eqtl;
  return (
    <div className="input_container">
      <Spin tip="Loading..." spinning={isLoading || isLoadingForSummary}>
        <div className="ResultItem">
          {summaryInfo?.eqtl ? (
            <Row className="font-weight-format">Configurations</Row>
          ) : (
            <>
              <Title level={3}>Configurations</Title>
              <Divider />
            </>
          )}
          {!summaryInfo?.eqtl && (
            <Form
              form={fileForm}
              name="validate_other_1"
              {...formItemLayout}
              style={{ maxWidth: 600, marginTop: 20 }}
            >
              <Form.Item
                {...formItemLayout}
                name="file"
                label="GWAS file"
                rules={[{ required: true }]}
              >
                <LocalSingleFileUploader
                  // accept={validFiles.map((suffix) => `.${suffix}`).join()}
                  text="Click or drag file to this area to upload"
                  description="Maximun allow file size in 500MB"
                  progress={progress || undefined}
                  isValidFileFormat={isValidFileFormat}
                  {...fileUploadProps}
                />
              </Form.Item>
            </Form>
          )}
          <Form
            form={form}
            name="validate_other"
            {...formItemLayout}
            initialValues={initialValues}
            style={{ maxWidth: 600, marginTop: 20, position: "relative" }}
          >
            {summaryInfo?.log_file && (
              <>
                <Form.Item {...formItemLayout} name="log_file" label="log file">
                  <Input
                    placeholder="no log file"
                    disabled={false}
                    readOnly={readOnly}
                  />
                </Form.Item>
                <Button
                  className="ButtonDownload"
                  icon={<FundViewOutlined />}
                  disabled={summaryInfo.log_file.indexOf("http") === -1}
                  type="primary"
                  shape="circle"
                  target="_blank"
                  href={initialValues.log_file}
                ></Button>
              </>
            )}

            <Form.Item
              name="type"
              label="type"
              hasFeedback
              rules={[{ required: true, message: "Please select type!" }]}
            >
              <Select placeholder="Please select a type" disabled={readOnly}>
                <Option value="cc">cc</Option>
                <Option value="quant">quant</Option>
              </Select>
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="trait"
              label="trait name"
              rules={[{ required: true, message: "Please input trait name" }]}
            >
              <Input
                readOnly={readOnly}
                placeholder="Please input trait name"
              />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="sample_size"
              label="sample size"
              rules={[{ required: true, message: "Please input sample size" }]}
            >
              <InputNumber
                placeholder="Please input sample size"
                controls={false}
                style={{ width: "100%" }}
                readOnly={readOnly}
              />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="pvalue_threshold"
              label="pvalue threshold"
              rules={[
                { required: true, message: "Please input pvalue threshold" },
              ]}
            >
              <InputNumber
                placeholder="Please input pvalue threshold"
                controls={false}
                style={{ width: "100%" }}
                readOnly={readOnly}
              />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="snp"
              label="snp"
              rules={[{ required: true, message: "Please input snp" }]}
            >
              <Input readOnly={readOnly} placeholder="Please input snp" />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="chrom"
              label="chrom"
              rules={[{ required: true, message: "Please input chrom" }]}
            >
              <Input readOnly={readOnly} placeholder="Please input chrom" />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="position"
              label="position"
              rules={[{ required: true, message: "Please input position" }]}
            >
              <Input readOnly={readOnly} placeholder="Please input position" />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="effect_allele"
              label="effect_allele"
              rules={[
                { required: true, message: "Please input effect_allele" },
              ]}
            >
              <Input
                readOnly={readOnly}
                placeholder="Please input effect_allele"
              />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="other_allele"
              label="other_allele"
              rules={[{ required: true, message: "Please input other_allele" }]}
            >
              <Input
                readOnly={readOnly}
                placeholder="Please input other_allele"
              />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="p_value"
              label="pvalue"
              rules={[{ required: true, message: "Please input pvalue" }]}
            >
              <Input readOnly={readOnly} placeholder="Please input pvalue" />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="beta"
              label="beta"
              rules={[{ required: true, message: "Please input beta" }]}
            >
              <Input readOnly={readOnly} placeholder="Please input beta" />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="standard_error"
              label="se"
              rules={[{ required: true, message: "Please input se" }]}
            >
              <Input readOnly={readOnly} placeholder="Please input se" />
            </Form.Item>
            <Form.Item
              name="tools"
              label="tools"
              rules={[
                {
                  required: true,
                  message: "Please select tools!",
                  type: "array",
                },
              ]}
            >
              <Select
                disabled
                mode="multiple"
                placeholder="Please select tools"
              >
                {Object.entries(THRESHOLD_MAP_DETIAL).map((item: any) => (
                  <Option value={item[0]}>{item[1].label}</Option>
                ))}
              </Select>
            </Form.Item>
            <Form.Item
              name="eqtls"
              label="eqtls"
              rules={[
                {
                  required: true,
                  message: "Please select eqtls!",
                  type: "array",
                },
              ]}
            >
              <Select
                mode="multiple"
                placeholder="Please select eqtls"
                disabled={readOnly}
              >
                {eqtls?.map((item: any) => (
                  <Fragment key={Object.values(item)[0] as any}>
                    <Option value={Object.keys(item)[0]}>
                      {Object.keys(item)[0]}
                    </Option>
                  </Fragment>
                ))}
              </Select>
            </Form.Item>

            <Form.Item
              {...formItemLayout}
              name="p1"
              label="p1(coloc)"
              rules={[{ required: false }]}
            >
              <InputNumber
                style={{ width: "100%" }}
                placeholder="Please input p1"
                controls={false}
                readOnly={readOnly}
              />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="p2"
              label="p2(coloc)"
              rules={[{ required: false }]}
            >
              <InputNumber
                style={{ width: "100%" }}
                placeholder="Please input p2"
                controls={false}
                readOnly={readOnly}
              />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="p12"
              label="p12(coloc)"
              rules={[{ required: false }]}
            >
              <InputNumber
                style={{ width: "100%" }}
                placeholder="Please input p12"
                controls={false}
              />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="a0"
              label="a0(fastenloc)"
              rules={[{ required: false }]}
            >
              <InputNumber
                style={{ width: "100%" }}
                placeholder="Please input a0"
                controls={false}
                readOnly={readOnly}
              />
            </Form.Item>
            <Form.Item
              {...formItemLayout}
              name="a1"
              label="a1(fastenloc)"
              rules={[{ required: false }]}
            >
              <InputNumber
                style={{ width: "100%" }}
                placeholder="Please input a1"
                controls={false}
                readOnly={readOnly}
              />
            </Form.Item>
            {summaryInfo?.eqtl && (
              <>
                <Form.Item
                  {...formItemLayout}
                  name="submit_at"
                  label="submit time"
                  rules={[{ required: false }]}
                >
                  <Input style={{ width: "100%" }} readOnly={readOnly} />
                </Form.Item>
                <Form.Item
                  {...formItemLayout}
                  name="duration"
                  label="duration"
                  rules={[{ required: false }]}
                >
                  <Input style={{ width: "100%" }} readOnly={readOnly} />
                </Form.Item>
              </>
            )}

            {!summaryInfo?.eqtl && (
              <Form.Item wrapperCol={{ span: 12, offset: 6 }}>
                <Button
                  style={{ width: "120px" }}
                  type="primary"
                  htmlType="submit"
                  onClick={submitForm}
                >
                  Submit
                </Button>
                <Button
                  style={{ marginLeft: "20px", width: "120px" }}
                  onClick={resetFormHandler}
                >
                  Reset
                </Button>
              </Form.Item>
            )}
          </Form>
        </div>
      </Spin>
    </div>
  );
}
