import ReactECharts from "echarts-for-react";
import React, { forwardRef } from "react";

type Props = React.ComponentProps<typeof ReactECharts>;
const Echarts = forwardRef<ReactECharts, Props>((props, ref) => (
  <ReactECharts ref={ref} style={{ height: "100%" }} {...props} />
));

export default Echarts;
