import React, {
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import styled, { css } from "styled-components";
import * as echarts from "echarts";

import ecStat from "echarts-stat";
import { Pagination, Row, Spin } from "antd";
import { getTpmList } from "src/service/api/home";
export const Container = styled.div`
  display: flex;
  flex-direction: column;
  height: 480px;
  width: 100%;
  margin: auto;
`;

export default React.memo(function GeneTpmComponent(props: {
  gene_id: string;
}) {
  const { gene_id } = props;
  const [isLoading, setIsloading] = useState<boolean>(false);
  const chartRef = useRef<any>(null);
  useEffect(() => {
    (async () => {
      try {
        setIsloading(true);
        const data = await getTpmList({
          page: 0,
          page_size: 50,
          gene_id: gene_id,
        });
        let chartDom = chartRef.current;
        let myChart = echarts.init(chartDom, "", { renderer: "svg" });
        echarts.registerTransform((ecStat as any).transform.regression);
        const option: any = {
          xAxis: {
            type: "category",
            data: data?.data?.data?.list?.map((item: any) => item.tissue),
            splitArea: {
              show: true,
            },
            axisLabel: {
              interval: 0,
              rotate: 45,
            },
          },
          grid: {
            height: "40%",
            top: "10%",
            left: "120px",
          },
          yAxis: {
            type: "value",
            name: "gene median tpm",
          },
          series: [
            {
              data: data?.data?.data?.list?.map((item: any) => item.value),
              type: "bar",
            },
          ],
        };
        option && myChart.setOption(option);
        setIsloading(false);
      } catch (error) {
        setIsloading(false);
      }
    })();
    return () => {};
  }, [gene_id]);

  return (
    <div className="gwasPlot">
      <Spin tip="Loading..." spinning={isLoading}>
        <Row className="tissue-row-title juxtify-content-center font-weight-format">
          GTEx Gene Expression
        </Row>

        <div
          style={{ width: "100%", height: "450px" }}
          id="gene_tmp_chart"
          ref={chartRef}
        />
      </Spin>
    </div>
  );
});
