import React, { useEffect, useState } from "react";
import * as _ from "lodash";
import { Descriptions, Row, Spin, Table } from "antd";
import { getColocConfig, getGenomicLoci } from "src/service/api/home";
import InputPage from "../InputPage";

export default React.memo(function GwasInfoComponent(props: {
  task_id: number;
  summaryInfo: any;
  isLoadingForSummary: any;
}) {
  const { task_id, summaryInfo, isLoadingForSummary } = props;
  const [dataSource, setDataSource] = useState<any>([]);

  const [isLoadingForClumping, setIsloadingForClumping] =
    useState<boolean>(false);

  useEffect(() => {
    (async () => {
      try {
        setIsloadingForClumping(true);
        const data = await getGenomicLoci(task_id);
        setDataSource(
          data?.data?.data?.map((item: any, index: any) => ({
            ...item,
            index: index + 1,
          }))
        );
        setIsloadingForClumping(false);
      } catch (error) {
        setIsloadingForClumping(false);
      }
    })();
  }, [task_id]);

  const columns = [
    {
      title: "rsID",
      dataIndex: "rs_id",
      key: "rs_id",
    },
    {
      title: "start",
      dataIndex: "start",
      key: "start",
    },
    {
      title: "end",
      dataIndex: "end",
      key: "end",
    },
    {
      title: "variant id",
      dataIndex: "var_id",
      key: "var_id",
    },
    {
      title: "total_snp",
      dataIndex: "total_snp",
      key: "total_snp",
    },
  ];
  return (
    <div className="GwasContainer">
      {summaryInfo?.eqtl && (
        <InputPage
          isLoadingForSummary={isLoadingForSummary}
          summaryInfo={summaryInfo}
        />
      )}
      <Row className="row-margin font-weight-format margin-top">
        clumping table
      </Row>
      <Table
        loading={isLoadingForClumping}
        rowKey={"index"}
        dataSource={dataSource}
        columns={columns as any}
      />
    </div>
  );
});
