import React, {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
} from "react";
import icon_png from "../../icon.png";
import {
  DesktopOutlined,
  ProfileOutlined,
  UserOutlined,
  ExperimentOutlined,
  KeyOutlined,
  CalendarOutlined,
} from "@ant-design/icons";

import { Affix, Avatar, Button, MenuProps } from "antd";
import {
  HomeOutlined,
  FileUnknownOutlined,
  FileOutlined,
  PaperClipOutlined,
  AreaChartOutlined,
  LineChartOutlined,
  AppstoreOutlined,
} from "@ant-design/icons";
import { Breadcrumb, Layout, Menu, theme } from "antd";
import {
  Link,
  Route,
  HashRouter,
  Outlet,
  useLocation,
  useNavigate,
} from "react-router-dom";
import styled from "styled-components";

const { Header, Content, Footer, Sider } = Layout;
type MenuItem = Required<MenuProps>["items"][number];

function getItem(
  label: React.ReactNode,
  key: React.Key,
  icon?: React.ReactNode,
  children?: MenuItem[]
): MenuItem {
  return {
    key,
    icon,
    children,
    label,
  } as MenuItem;
}

const AvatarDiv = styled(Avatar)`
  flex: none;
`;
const SiteLayout = styled(Layout)``;

const items: MenuItem[] = [
  getItem(
    "Home",
    "1",
    <Link to="/home">
      <HomeOutlined style={{ fontSize: "18px" }} />
    </Link>
  ),
  getItem(
    "Tutorial",
    "2",
    <Link to="/home/tutorial">
      <KeyOutlined style={{ fontSize: "18px" }} />
    </Link>
  ),
  getItem(
    "Reference",
    "5",
    <Link to="/home/reference">
      <PaperClipOutlined style={{ fontSize: "18px" }} />
    </Link>
  ),
];

const myItems: MenuItem[] = [
  getItem(
    "Run Analysis",
    "4",
    <Link to="/home/analysis">
      <AreaChartOutlined style={{ fontSize: "18px" }} />
    </Link>
    // [
    //   getItem(
    //     "Input",
    //     "6",
    //     <Link to="/home/analysis/input">
    //       <ProfileOutlined style={{ fontSize: "18px" }} />
    //     </Link>
    //   ),
    // ]
  ),
  getItem(
    "Tasks",
    "8",
    <Link to="/home/tasks">
      <ExperimentOutlined style={{ fontSize: "18px" }} />
    </Link>
  ),
];
interface AuthContextType {
  isLogin: boolean;
}
const AuthContext = createContext<AuthContextType>({
  isLogin: false,
});

const HomePage: React.FC = () => {
  const [collapsed, setCollapsed] = useState(false);
  const location = useLocation();
  const [selectedKeys, setSelectedKeys] = useState(
    [...items, ...myItems]
      .filter((item: any) => {
        return (
          location.pathname.endsWith(item.icon.props.to as string) ||
          (location.pathname.endsWith("home/analysis/results") &&
            item.icon.props.to === "/home/tasks")
        );
      })
      .map((item: any) => item.key as string)
  );
  const navigate = useNavigate();
  useEffect(() => {
    if (location.state?.menuKey) {
      setSelectedKeys(location.state?.menuKey);
    }
  }, [location.state?.menuKey]);
  return (
    <AuthContext.Provider
      value={useMemo(
        () => ({
          isLogin: location.state?.login || localStorage.getItem("token"),
        }),
        [location.state?.login]
      )}
    >
      <Layout style={{ height: "100%", width: "100%" }}>
        <Sider
          style={{
            position: "relative",
            height: "100%",
            width: "56px",
            isolation: "isolate",
          }}
          theme="light"
          collapsed={collapsed}
          onCollapse={(value) => setCollapsed(value)}
        >
          <div
            style={{
              height: 32,
              lineHeight: "32px",
              margin: 16,
              textAlign: "center",
              background: "rgba(255, 255, 255, 0.2)",
              whiteSpace: "nowrap",
              overflow: "hidden",
              textOverflow: "ellipsis",
              fontSize: "18px",
              fontWeight: 500,
            }}
          >
            LocusCompare v2
          </div>
          <Menu
            theme="light"
            selectedKeys={selectedKeys}
            onClick={({ item, key, keyPath, domEvent }) =>
              setSelectedKeys([key])
            }
            style={{ fontSize: "16px", fontWeight: 400 }}
            mode="inline"
            items={[...items, ...myItems]}
          />
          {location.state?.login || localStorage.getItem("token") ? (
            <Affix className="AffixDiv" offsetTop={10}>
              <div className="Profile">
                <div>
                  <AvatarDiv
                    onClick={() => {
                      navigate("/home/profile");
                      setSelectedKeys([""]);
                    }}
                    size={40}
                    style={{ backgroundColor: "#1890ff" }}
                    icon={<UserOutlined />}
                  />
                </div>
              </div>
            </Affix>
          ) : (
            <Affix
              className="AffixDiv"
              offsetTop={10}
              style={{ textAlign: "center", fontSize: "16px", fontWeight: 500 }}
            >
              <Link to="/login">To Login Or Register</Link>
            </Affix>
          )}
        </Sider>
        <SiteLayout>
          <div
            style={{
              padding: "0px 20px",
              background: "rgb(248 249 250)",
              overflow: "auto",
              height: "100%",
            }}
          >
            <Content
              style={{
                height: "100%",
                padding: "20px 0",
              }}
            >
              <Outlet />
            </Content>
          </div>
        </SiteLayout>
      </Layout>
    </AuthContext.Provider>
  );
};

export function useAuthorize() {
  return useContext(AuthContext);
}

export default HomePage;
